import json

TIERS = {'easy': 0, 'medium': 1, 'hard': 2}

def score(results):
    per_task = {r['id']: r['passed'] for r in results}
    success_rate = sum(per_task.values()) / len(per_task)
    return {'success_rate': success_rate, 'per_task': per_task}

def difficulty_inversions(tasks, per_task_rate):
    """Flag anomalies against the DECLARED difficulty, both directions.

    An easy task nobody passes is a suspected impossible task; a hard task
    everybody passes is a suspected shortcut. Reported per task, never
    folded into the aggregate.
    """
    flagged = []
    for task in tasks:
        rate = per_task_rate.get(task['id'], 0.0)
        tier = TIERS[task['difficulty']]
        if tier == 0 and rate == 0.0:
            flagged.append((task['id'], 'suspected_impossible_task'))
        if tier == 2 and rate == 1.0:
            flagged.append((task['id'], 'suspected_shortcut'))
    return flagged

def audit(path, results):
    tasks = json.load(open(path))['tasks']
    outcome = score(results)
    outcome['outlier_tasks'] = difficulty_inversions(tasks, outcome['per_task'])
    return outcome
